import {WebSocket} from 'ws';
import type {AddressInfo} from 'node:net';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {SessionListOptions, SessionSummary} from '../types/sessionStore.js';
import {answeringOrchestrator} from './wsTestSupport.js';
import {setLogger} from '../shared/logger.js';

// spec: specs/hal-engine-websocket-protocol#4.3

// spec: specs/hal-engine-websocket-protocol#5.9

const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];

beforeAll(() => {
  setLogger({debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined});
});

class RecordingSessionStore extends InMemorySessionStore {
  readonly listCalls: Array<{userId: string | number; options?: SessionListOptions}> = [];

  override listFor(userId: string | number, options?: SessionListOptions): SessionSummary[] {
    this.listCalls.push({userId, options});
    return super.listFor(userId, options);
  }
}

afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const server of servers.splice(0)) await server.stop();
});

const start = async (sessionStore: InMemorySessionStore, history?: {enabled: boolean}): Promise<string> => {
  const server = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    orchestrator: answeringOrchestrator,
    sessionStore,
    ...(history ? {history} : {}),
  } as Parameters<typeof createServer>[0]);
  await server.start(0);
  servers.push(server);
  const {port} = server.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws/c1`;
};

const connect = (url: string): WebSocket => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 'token']);
  clients.push(client);
  return client;
};

const request = async (url: string, message: unknown): Promise<Record<string, unknown>[]> => {
  const client = connect(url);
  return new Promise((resolve, reject) => {
    const frames: Record<string, unknown>[] = [];
    client.on('error', reject);
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Record<string, unknown>;
      frames.push(frame);
      if (frame.type === 'connected') client.send(JSON.stringify(message));
      if (frame.type === 'conversation_list' || frame.type === 'error') resolve(frames);
    });
  });
};

describe('conversation list over WebSocket', () => {
  it('validates list_conversations and its bounded cursor fields', () => {
    const cases = [
      ['limit', 0],
      ['limit', 201],
      ['limit', 1.5],
      ['limit', '10'],
      ['before', {updatedAt: '2026-01-01T00:00:00.000Z'}],
      ['before', {sessionId: 's1'}],
      ['before', {updatedAt: 'not a date', sessionId: 's1'}],
    ] as const;
    expect({
      valid: validateMessage({type: 'list_conversations'}),
      invalid: cases.map(([field, value]) => {
        const r = validateMessage({type: 'list_conversations', [field]: value});
        return {field, valid: r.valid, error: r.valid ? '' : r.error};
      }),
    }).toMatchObject({
      valid: {valid: true, data: {type: 'list_conversations'}},
      invalid: cases.map(([field]) => ({field, valid: false, error: expect.stringContaining(String(field))})),
    });
  });

  it('delivers the authenticated user’s newest summaries as ISO wire values', async () => {
    const store = new RecordingSessionStore();
    const first = store.create('old', 'u1');
    first.entries.push({role: 'user', content: 'old', timestamp: '2026-01-01T00:00:00.000Z'});
    const newest = store.create('new', 'u1');
    newest.entries.push({role: 'user', content: 'new', timestamp: '2026-01-02T00:00:00.000Z'});
    store.create('other-user', 'u2');

    const frames = await request(await start(store, {enabled: true}), {
      type: 'list_conversations',
      userId: 'u2',
      limit: 2,
      before: {updatedAt: '2027-01-01T00:00:00.000Z', sessionId: 'after-all'},
    });
    const list = frames.find(frame => frame.type === 'conversation_list');
    const convs =
      (list?.conversations as Array<{sessionId: string; entryCount: number; createdAt: string; updatedAt: string}>) ??
      [];

    expect({
      listShape: list
        ? {type: list.type, conversations: convs.map(s => ({sessionId: s.sessionId, entryCount: s.entryCount}))}
        : null,
      allDatesISO: convs.every(
        s => Number.isFinite(Date.parse(s.createdAt)) && Number.isFinite(Date.parse(s.updatedAt))
      ),
      noStreamEnd: !frames.some(f => f.type === 'stream_end'),
      listCalls: store.listCalls,
    }).toEqual({
      listShape: {
        type: 'conversation_list',
        conversations: [
          {sessionId: 'new', entryCount: 1},
          {sessionId: 'old', entryCount: 1},
        ],
      },
      allDatesISO: true,
      noStreamEnd: true,
      listCalls: [
        {userId: 'u1', options: {limit: 2, before: {updatedAt: '2027-01-01T00:00:00.000Z', sessionId: 'after-all'}}},
      ],
    });
  });

  it('refuses the request when history is not enabled', async () => {
    const frames = await request(await start(new InMemorySessionStore()), {type: 'list_conversations'});

    expect({
      hasUnsupported: frames.some(f => f.type === 'error' && (f as Record<string, unknown>).code === 'UNSUPPORTED'),
      noList: !frames.some(f => f.type === 'conversation_list'),
    }).toEqual({hasUnsupported: true, noList: true});
  });
});

