  const validate = MESSAGE_VALIDATORS[message.type];
  if (!validate) return {valid: false, error: `Unknown message type: ${message.type}`};
  return validate(message);
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined && (isInvalidLimit(message.limit) || isOutOfRange(message.limit as number))) {
    return {valid: false, error: 'limit must be an integer between 1 and 200'};
  }
  if (message.before !== undefined) return validateWithCursor(message);
  return {valid: true, data: assembleListMsg(message)};
}

function validateWithCursor(message: Record<string, unknown>): ValidationResult {
  const cursorResult = validateCursor(message.before);
  if ('error' in cursorResult) return {valid: false, error: cursorResult.error};
  return {valid: true, data: assembleListMsg(message, cursorResult.cursor)};
}

function isInvalidLimit(value: unknown): boolean {
  return typeof value !== 'number' || !Number.isInteger(value as number);
}

function isOutOfRange(value: number): boolean {
  return value < 1 || value > 200;
}

function assembleListMsg(message: Record<string, unknown>, before?: ConversationCursor): ListConversationsMessage {
  const validated: ListConversationsMessage = {type: 'list_conversations'};
  if (before !== undefined) validated.before = before;
  if (message.limit !== undefined) validated.limit = message.limit as number;
  return validated;
}

function validateCursor(raw: unknown): {cursor: ConversationCursor} | {error: string} {
  if (typeof raw !== 'object' || raw === null) {
    return {error: 'before must be a cursor object with updatedAt and sessionId'};
  }
  const fields = raw as Record<string, unknown>;
  if (typeof fields.sessionId !== 'string') {
    return {error: 'before must have a sessionId string'};
  }
  if (typeof fields.updatedAt !== 'string' || !Number.isFinite(Date.parse(fields.updatedAt))) {
    return {error: 'before.updatedAt must be a valid date string'};
  }
  return {cursor: {updatedAt: fields.updatedAt, sessionId: fields.sessionId}};
}

